def hooks(module):
    code = (A / {'youtube': 'YouTube', 'instagram': 'Instagram', 'tiktok': 'TikTok', 'soundcloud': 'SoundCloud', 'reddit': 'Reddit', 'youtubemusic': 'YouTubeMusic', 'x': 'X', 'messenger': 'Messenger', 'facebook': 'Facebook', 'amazon': 'Amazon', 'threads': 'Threads', 'gmail': 'Gmail', 'appstore': 'AppStore', 'douban': 'Douban', 'qqmusic': 'QQMusic', 'sogou': 'Sogou', 'wechat': 'WeChat', 'bilibili': 'Bilibili'}[module] / 'Module.m').read_text()
    out = [f'{c} {s}' for c, s in re.findall(r'\{"([\w.$]+)","([\w:]+)"', code)] + [f'{c} {s}' for c, s in re.findall(r'MYBBilibiliHook\("([\w.$]+)","([\w:]+)"', code)] + [f'{c} {s}' for c, s in re.findall(r'MYBAdsHookNamed\("([\w.$]+)","([\w:]+)"', code)]
    return list(dict.fromkeys(out))
def build():
    cat = re.findall(r'@\{@"module":@"(\w+)",@"name":@"([^"]+)",@"bundles":@\[([^\]]*)\]', (root / 'Shared/MYBInAppAds.h').read_text())
    mods = {}
    for module, name, bundles in cat:
        hs = hooks(module); ev = EVID.get(module, {}) or {h: [SRCMAP[module]] for h in hs if module in SRCMAP}
        mods[module] = {'app': name, 'bundles': re.findall(r'"([^"]+)"', bundles), 'note': NOTES[module], 'device_verified': '',
                        'hooks': {h: {'sources': ev.get(h, [])} for h in hs}}
    return {'schema': 1, 'retrieved': '2026-11-16', 'modules': mods}
FOLDER = {'youtube': 'YouTube', 'instagram': 'Instagram', 'tiktok': 'TikTok', 'soundcloud': 'SoundCloud', 'reddit': 'Reddit', 'youtubemusic': 'YouTubeMusic', 'x': 'X', 'messenger': 'Messenger', 'facebook': 'Facebook', 'amazon': 'Amazon', 'threads': 'Threads', 'gmail': 'Gmail', 'appstore': 'AppStore', 'douban': 'Douban', 'qqmusic': 'QQMusic', 'sogou': 'Sogou', 'wechat': 'WeChat', 'bilibili': 'Bilibili'}
NATIVE = {'youtube': 'inappads-native.m', 'instagram': 'inappads-native.m', 'soundcloud': 'inappads-native.m', 'reddit': 'inappads-native.m', 'tiktok': 'inappads-tiktok-native.m',
          'youtubemusic': 'inappads-more-native.m', 'x': 'inappads-more-native.m', 'messenger': 'inappads-more-native.m', 'facebook': 'inappads-facebook-native.m', 'amazon': 'inappads-amazon-native.m', 'threads': 'inappads-rules-native.m', 'gmail': 'inappads-rules-native.m', 'appstore': 'inappads-discovery-native.m', 'douban': 'inappads-rules-native.m', 'qqmusic': 'inappads-rules-native.m', 'sogou': 'inappads-rules-native.m', 'wechat': 'inappads-rules-native.m', 'bilibili': 'inappads-bilibili-native.m'}
def matrix(data):
    mk = (root / 'Makefile').read_text(); ui = (root / 'Preferences/MYBInAppAdsController.m').read_text()
    L = ['# In-app ad module matrix', '', 'Generated by `tools/generate-inappads-evidence.py` from the catalogue, each module\'s Makefile, filter plist and Module.m, and `evidence.json`. Do not edit by hand. One shared dylib (`MYBInAppAds.dylib`) now carries every module.', '',
         'Reading the columns: **Built** = the module is a Makefile subproject and a tweak of its own; **Packaged** = its dylib and filter plist are checked in the package by CI (`tests/verify-package.py`, which also needs arm64 and arm64e); **Visible** = the app appears in Settings > In-App Ad Blocking when installed, and its status is listed. **Interface source** says where the class and selector names come from. It is evidence that the interface exists, **not** evidence that ads are removed in a given app version. **Device-verified** is empty for every module: none has been run on a device.', '',
         '| Module | App (bundle ids) | Built | Packaged | Visible | Hooks | Interface sources | Executed locally | Pending CI test | Device-verified |', '|---|---|---|---|---|---|---|---|---|---|']
    for m, v in data['modules'].items():
        f = FOLDER[m]; tw = 'MYBInAppAds'
        shared = (A / 'Makefile').read_text()
        built = 'Companions/InAppAds' in mk and ('TWEAK_NAME = ' + tw) in shared and ('%s/Module.m' % f) in shared
        plist = ('"%s"' % v['bundles'][0]) in (A / 'MYBInAppAds.plist').read_text() if v['bundles'] else False
        vis = 'MYBAdsCatalogue()' in ui
        hs = v['hooks']; sourced = sum(1 for h in hs.values() if h['sources'])
        srcs = sorted({'%s (%s)' % ((x['url'].split('github.com/')[1].split('/blob/')[0] if 'github.com/' in x['url'] else 'Apple public API'), x['repo_last_commit']) for h in hs.values() for x in h['sources']})
        L.append('| %s | %s (%s) | %s | shared dylib `%s.dylib` + filter %s | %s | %d, %d with a source | %s | static source checks (`tests/inappads-source.py`), evidence check (`tests/inappads-evidence.py`) | `tests/%s` (needs macOS CI) | none |' % (
            m, v['app'], ', '.join(v['bundles']), 'yes' if built else 'NO', tw, 'present' if plist else 'MISSING', 'yes' if vis else 'NO', len(hs), sourced, '; '.join(srcs) or 'none', NATIVE[m]))
    L += ['', '## Notes per module', ''] + ['- **%s**: %s' % (v['app'], v['note']) for v in data['modules'].values()]
    L += ['', '## Hooks', '']
    for m, v in data['modules'].items():
        L += ['### ' + v['app'], '', '| Class / selector | Source |', '|---|---|'] + ['| `%s` | %s |' % (h, '; '.join('[%s](%s) - %s' % (x['kind'], x['url'], x['shows']) for x in e['sources']) or 'none') for h, e in v['hooks'].items()] + ['']
    L += ['## Apps not implemented', '', 'Spotify, Twitch, LinkedIn, Pinterest, Snapchat, Tumblr, Pandora, Deezer and WhatsApp have no module: no runtime interface for them could be checked against a source in this work, and a guessed class name that does nothing is not a feature.', '']
    # Coverage counts: derived from the catalogue and the build, never typed by hand. Provenance is the Hooks column above.
    removal = [m for m, v in data['modules'].items() if v['hooks']]; disc = [m for m, v in data['modules'].items() if not v['hooks']]
    sdk = (root / 'Shared/MYBAdSDK.h').read_text()
    entries = re.findall(r'\{"(\w+)","[^"]+","[^"]+",\'[CBDNUVRL]\'', sdk); gaps = re.findall(r'\{"([^"]+)","not covered"', sdk)
    fam = lambda c: 'Google Mobile Ads' if c.startswith('GAD') else 'Meta Audience Network' if c.startswith('FB') else 'Vungle / Liftoff' if c.startswith('Vungle') else 'Unity Ads' if c.startswith('UnityAds') else 'Mintegral' if c.startswith('MTG') else 'LevelPlay' if c.startswith('LPM') else c
    L += ['## Coverage (derived from the catalogue and the build)', '',
          '- **Apps with ad-removal hooks: %d** (%s). Each has its own control and a rule/hook list in the matrix above; none is device-verified.' % (len(removal), ', '.join(removal)),
          '- **Discovery-only targets: %d** (%s). They collect interface names during a session and block nothing.' % (len(disc), ', '.join(disc)),
          '- **Shared SDK support:** %d entry points across %d SDK families (%s), applied only to apps the person selects under Ad Network Blocking. It is not a per-app module and adds nothing to the app counts above.' % (len(entries), len({fam(c) for c in entries}), ', '.join(sorted({fam(c) for c in entries}))),
          '- **SDKs not covered: %d** (%s); the specific blocker for each is in `SDK-AUDIT.md`.' % (len(gaps), ', '.join(gaps)), '']
    return '\n'.join(L)
if __name__ == '__main__':
    # The evidence is a review document, committed under docs/inappads and not packaged. It names the public sources of the interfaces
    # that were read; those projects' licences are in Companions/InAppAds/NOTICE.md. Default output: docs/inappads/.
    out = Path(sys.argv[sys.argv.index('--out') + 1]) if '--out' in sys.argv else root / 'docs/inappads'
    out.mkdir(parents=True, exist_ok=True)
    data = build(); (out / 'evidence.json').write_text(json.dumps(data, indent=1, sort_keys=True) + '\n'); (out / 'MATRIX.md').write_text(matrix(data))
    print('wrote', out / 'evidence.json', 'and', out / 'MATRIX.md')
